+                     bias_correction,
+                     params,
+                     grads,
+                     exp_avg,
+                     exp_avg_sq);
+    } catch (...) {
+        opt->set_grad_scale(1.0f);
+        throw;
+    }
+    opt->set_grad_scale(1.0f);
+    return 0;
+}
